#include <stdio.h>
#include <string.h>

int main() {
    char text[] = "the quick brown fox";
    char word[] = "brown";
    int tl = strlen(text);
    int wl = strlen(word);
    int pos = -1;
    for (int i = 0; i <= tl - wl; i++) {
        int match = 1;
        for (int j = 0; j < wl; j++) {
            if (text[i + j] != word[j]) {
                match = 0;
            }
        }
        if (match == 1 && pos == -1) {
            pos = i;
        }
    }
    printf("%d\n", pos);
    return 0;
}

